import * as U from '../ui.js';
let filter='open',q='',courseId='';
const update=U.mount(()=>{let tasks=U.db.tasks.filter(t=>(filter==='all'||filter==='open'&&!['done','cancelled'].includes(t.status)||filter==='done'&&t.status==='done'||t.task_type===filter)&&(!courseId||t.course_id===courseId)&&t.title.toLowerCase().includes(q.toLowerCase())).sort((a,b)=>(a.due_at||'z').localeCompare(b.due_at||'z'));return U.heading('One thing at a time','Tasks & deadlines.','From the first draft to the final submission.',U.button('Add a task','tasks'))+`<div class="toolbar"><div class="tabs">${[['open','Open'],['assignment','Assignments'],['exam','Exams'],['done','Completed'],['all','All']].map(([v,t])=>`<button class="${filter===v?'active':''}" data-filter="${v}">${t}</button>`).join('')}</div><div class="filters"><input class="search" id="search" aria-label="Search tasks" placeholder="Search your tasks…" value="${U.esc(q)}"><select id="course-filter" aria-label="Filter by course"><option value="">All courses</option>${U.db.courses.map(c=>`<option value="${c.id}" ${courseId===c.id?'selected':''}>${U.esc(c.course_code)}</option>`).join('')}</select></div></div>${U.section('Your task list',tasks.map(t=>U.taskRow(t)+`${['assignment','exam'].includes(t.task_type)?`<div style="padding:0 0 12px 31px"><button class="text-link" style="background:none;border:0;padding:0;cursor:pointer" data-form="tasks" data-defaults="${U.esc(JSON.stringify({task_type:'study',course_id:t.course_id,parent_task_id:t.id,title:'Study: '+t.title,planned_start_at:U.TODAY+'T17:00',planned_end_at:U.TODAY+'T18:00'}))}">+ Break into study tasks</button></div>`:''}`).join('')||U.empty('No tasks match this view.'),U.tag(tasks.length+' tasks'))}<div class="note" style="margin-top:20px">${U.icon('study')}<span>A deadline is easier to handle when it has a plan. Break an assignment or exam into smaller study tasks, then give each one a time.</span></div>`});
document.addEventListener('click',e=>{let f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;update()}});document.addEventListener('input',e=>{if(e.target.id==='search'){let pos=e.target.selectionStart;q=e.target.value;update();let el=document.querySelector('#search');el.focus();el.setSelectionRange(pos,pos)}});document.addEventListener('change',e=>{if(e.target.id==='course-filter'){courseId=e.target.value;update()}});
